    # ---------- 213. 赠越僧岳云二首 ----------
    {
        "id": "wen-ting-yun-213",
        "title": "赠越僧岳云二首",
        "author": "温庭筠",
        "poet_id": "wen-ting-yun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷18》",
        "verse": [
            "世机消已尽，巾屦亦飘然。一室故山月，满瓶秋涧泉。",
            "禅庵过微雪，乡寺隔寒烟。应共白莲客，相期松桂前。",
            "兰亭旧都讲，今日意如何。有树关深院，无尘到浅莎。",
            "僧居随处好，人事出门多。不及新春雁，年年镜水波。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 214. 咏山鸡 ----------
