    # ---------- 324. 杨柳八首（一作杨柳枝） ----------
    {
        "id": "wen-ting-yun-324",
        "title": "杨柳八首（一作杨柳枝）",
        "author": "温庭筠",
        "poet_id": "wen-ting-yun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷54》",
        "verse": [
            "宜春苑外最长条，闲袅春风伴舞腰。",
            "正是玉人肠断处，一渠春水赤阑桥。",
            "南内墙东御路旁，预知春色柳丝黄。",
            "杏花未肯无情思，何是情人最断肠。",
            "苏小门前柳万条，毵毵金线拂平桥。",
            "黄莺不语东风起，深闭朱门伴细腰。",
            "金缕毵毵碧瓦沟，六宫眉黛惹春愁。",
            "晚来更带龙池雨，半拂阑干半入楼。",
            "馆娃宫外邺城西，远映征帆近拂堤。",
            "系得王孙归意切，不关春草绿萋萋。",
            "两两黄鹂色似金，袅枝啼露动芳音。",
            "春来幸自长如线，可惜牵缠荡子心。",
            "御柳如丝映九重，凤凰窗柱绣芙蓉。",
            "景阳楼畔千条露，一面新妆待晓钟。",
            "织锦机边莺语频，停梭垂泪忆征人。",
            "塞门三月犹萧索，纵有垂杨未觉春。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
