    # ---------- 340. 定西番 ----------
    {
        "id": "wen-ting-yun-340",
        "title": "定西番",
        "author": "温庭筠",
        "poet_id": "wen-ting-yun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷12》",
        "verse": [
            "汉使昔年离别，攀弱柳，折寒梅，上高台。",
            "千里玉关春雪，雁来人不来。羌笛一声愁绝，月裴回。",
            "海燕欲飞调羽，萱草绿，杏花红，隔帘栊。",
            "双鬓翠霞金缕，一枝春艳浓。楼上月明三五，琐窗中。",
            "细雨晓莺春晚，人似玉，柳如眉，正相思。",
            "罗幕翠帘初卷，镜中花一枝。肠断塞门消息，雁来稀。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
