            "自有晚风推楚浪，不劳春色染湘烟。（《次洞庭南》）",
            "卓氏垆前金线柳，隋家堤畔锦帆风。（《题池亭》）",
            "门外白云何处雨，一条清涧绕溪流。（失题）",
